const adminUsersFull = `-- name: AdminUsersFull :many
SELECT u.id, u.email, u.name, u.avatar_url, u.role, u.status, u.locale, u.created_at, u.last_login_at, u.admin_note,
       (u.password_hash IS NOT NULL)::boolean AS has_password, (u.google_sub IS NOT NULL)::boolean AS has_google,
       coalesce(w.balance_micro, 0)::bigint AS balance_micro,
       coalesce(s.plan_id, '')::text AS plan_id,
       s.ends_at AS plan_ends_at,
       coalesce(r.requests, 0)::bigint AS requests_30d,
       coalesce(r.spend, 0)::bigint AS spend_30d,
       coalesce(r.last_request_at, 'epoch'::timestamptz)::timestamptz AS last_request_at,
       coalesce(p.paid, 0)::bigint AS paid_kopecks,
       (SELECT count(*) FROM api_keys k WHERE k.user_id = u.id AND k.revoked_at IS NULL AND k.kind = 'inference')::bigint AS keys
FROM users u
LEFT JOIN wallets w ON w.user_id = u.id
LEFT JOIN subscriptions s ON s.user_id = u.id AND s.status = 'active'
LEFT JOIN LATERAL (
    SELECT count(*) AS requests, sum(cost_micro) AS spend, max(created_at) AS last_request_at
    FROM requests WHERE user_id = u.id AND created_at >= now() - interval '30 days'
) r ON true
LEFT JOIN LATERAL (
    SELECT sum(amount_kopecks) AS paid FROM payments WHERE user_id = u.id AND status = 'succeeded'
) p ON true
WHERE ($1::text = '' OR u.email ILIKE '%' || $1 || '%' OR u.name ILIKE '%' || $1 || '%' OR u.id::text = $1)
  AND ($2::text = '' OR u.role = $2)
  AND ($3::text = '' OR u.status = $3)
  AND ($4::text = '' OR ($4 = 'none' AND s.plan_id IS NULL) OR s.plan_id = $4)
ORDER BY
  CASE WHEN $5::text = 'balance' THEN coalesce(w.balance_micro, 0) END DESC NULLS LAST,
  CASE WHEN $5::text = 'spend' THEN coalesce(r.spend, 0) END DESC NULLS LAST,
  CASE WHEN $5::text = 'requests' THEN coalesce(r.requests, 0) END DESC NULLS LAST,
  CASE WHEN $5::text = 'paid' THEN coalesce(p.paid, 0) END DESC NULLS LAST,
  CASE WHEN $5::text = 'active' THEN r.last_request_at END DESC NULLS LAST,
  u.created_at DESC
LIMIT $7 OFFSET $6
`

type AdminUsersFullParams struct {
	Q      string `json:"q"`
	Role   string `json:"role"`
	Status string `json:"status"`
	Plan   string `json:"plan"`
	Sort   string `json:"sort"`
	Off    int32  `json:"off"`
	Lim    int32  `json:"lim"`
}

type AdminUsersFullRow struct {
	ID            uuid.UUID  `json:"id"`
	Email         string     `json:"email"`
	Name          string     `json:"name"`
	AvatarUrl     string     `json:"avatar_url"`
	Role          string     `json:"role"`
	Status        string     `json:"status"`
	Locale        string     `json:"locale"`
	CreatedAt     time.Time  `json:"created_at"`
	LastLoginAt   *time.Time `json:"last_login_at"`
	AdminNote     string     `json:"admin_note"`
	HasPassword   bool       `json:"has_password"`
	HasGoogle     bool       `json:"has_google"`
	BalanceMicro  int64      `json:"balance_micro"`
	PlanID        string     `json:"plan_id"`
	PlanEndsAt    *time.Time `json:"plan_ends_at"`
	Requests30d   int64      `json:"requests_30d"`
	Spend30d      int64      `json:"spend_30d"`
	LastRequestAt time.Time  `json:"last_request_at"`
	PaidKopecks   int64      `json:"paid_kopecks"`
	Keys          int64      `json:"keys"`
}

func (q *Queries) AdminUsersFull(ctx context.Context, arg AdminUsersFullParams) ([]AdminUsersFullRow, error) {
	rows, err := q.db.Query(ctx, adminUsersFull,
		arg.Q,
		arg.Role,
		arg.Status,
		arg.Plan,
		arg.Sort,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AdminUsersFullRow{}
	for rows.Next() {
		var i AdminUsersFullRow
		if err := rows.Scan(
			&i.ID,
			&i.Email,
			&i.Name,
			&i.AvatarUrl,
			&i.Role,
			&i.Status,
			&i.Locale,
			&i.CreatedAt,
			&i.LastLoginAt,
			&i.AdminNote,
			&i.HasPassword,
			&i.HasGoogle,
			&i.BalanceMicro,
			&i.PlanID,
			&i.PlanEndsAt,
			&i.Requests30d,
			&i.Spend30d,
			&i.LastRequestAt,
			&i.PaidKopecks,
			&i.Keys,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

